entries.content:
{
  "林曦瑶": {
    "对{{user}}的好感度": [
      30,
      "表示林曦瑶对{{user}}的好感程度，取值范围0-100。根据{{user}}的正面（如关心、理解、保护）或负面（如忽视、让她难堪）行为增减，单次变动1-5点。正面行为增加，负面行为减少。"
    ],
    "傲娇度": [
      100,
      "表示林曦瑶傲娇的程度，取值范围0-100。当她感受到{{user}}的真诚、耐心和可靠，确认自己处于一个安全的环境，可以不必伪装时，傲娇度会减小；当进行亲密互动时傲娇度会减小；当她的内心（害羞、喜悦、关心等真实情感）即将暴露，或者自尊心受到挑战时，傲娇度会增加。单次变动1-10点。"
    ]
  },
  "剧情变量": {
    "{{user}}已回忆起幼时": [
      false,
      "标记{{user}}是否已经回忆起与林曦瑶幼时的共同回忆。仅在剧情中发生特定触发事件，明确表明{{user}}回忆起过去时，此值才变为true，并且一旦变为true后不再改变。"
    ]
  }
}

